// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate, random, Easing } from '../remotionShim';
// Start Google Fonts Loader
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); // super light + stable

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700;900`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
// End Google Fonts Loader



export type VoxStyleProfileProps = Record<string, any>;

const DotGridOverlay: React.FC = () => (
  <svg
    style={{
      position: "absolute",
      top: 0,
      left: 0,
      width: "100%",
      height: "100%",
      pointerEvents: "none",
      zIndex: 9997, // Moved to apply on top of all animation elements
      opacity: 0.12,
      mixBlendMode: "multiply", // Blend nicely with the elements below
    }}
  >
    <defs>
      <pattern
        id="dotGrid"
        width="20"
        height="20"
        patternUnits="userSpaceOnUse"
      >
        <circle cx="2" cy="2" r="1.5" fill="#000" />
      </pattern>
    </defs>
    <rect width="100%" height="100%" fill="url(#dotGrid)" />
  </svg>
);

const NoiseOverlay: React.FC = () => (
  <svg
    viewBox="0 0 200 200"
    preserveAspectRatio="none" // Stretch safely across the entire 16:9 canvas
    xmlns="http://www.w3.org/2000/svg"
    style={{
      position: "absolute",
      top: 0,
      left: 0,
      width: "100%",
      height: "100%",
      opacity: 0.15,
      pointerEvents: "none",
      mixBlendMode: "multiply",
      zIndex: 9999, // Absolute top layer
    }}
  >
    <filter id="noiseFilter">
      <feTurbulence
        type="fractalNoise"
        baseFrequency="0.8"
        numOctaves="3"
        stitchTiles="stitch"
      />
    </filter>
    <rect width="100%" height="100%" filter="url(#noiseFilter)" />
  </svg>
);

const VoxStyleProfile: React.FC<VoxStyleProfileProps> = ({
  backgroundColor = "#F2EFEB",
  transparentBackground = false,
  durationInSeconds = 8,
  targetNumber = 25,
  primaryTextColor = "#D93B48",
  mainWord = "years",
  subtextWord = "in the game",
  profileImages = [
    "https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?q=80&w=800&auto=format&fit=crop",
    "https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?q=80&w=800&auto=format&fit=crop",
    "https://images.unsplash.com/photo-1500648767791-00dcc994a43e?q=80&w=800&auto=format&fit=crop"
  ],
  framesPerFlip = 8,
  paperTexture = "https://images.unsplash.com/photo-1586075010923-2dd4570fb338?q=80&w=1920&auto=format&fit=crop",
  profileImageSize = 0.35,
  
  mainWordFontSize = 0.25,
  mainWordOffsetX = 0.4,
  mainWordOffsetY = -0.5,
  
  numberFontSize = 0.45,
  numberOffsetX = -1.6,
  numberOffsetY = -0.8,
  
  subtextFontSize = 0.1,
  subtextOffsetX = 0.2,
  subtextOffsetY = 0.2,
}) => {
  // Load Google Fonts
  useFontLoader(["Abril Fatface", "Caveat"]);
  // End Load Google Fonts

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  
  // Layout scaling
  const s = Math.min(width, height);
  const circleRadius = s * profileImageSize;
  const centerX = width / 2;
  const centerY = height / 2;

  // --- Animations ---

  // 1. Center Circle Animation
  const circleEntrance = spring({
    frame: frame - 10,
    fps,
    config: { damping: 14, mass: 0.8 },
  });

  // 2. Image Flip Logic (Stop-motion feel)
  const flipSeed = Math.floor(frame / framesPerFlip);
  const currentImageIndex = flipSeed % Math.max(1, profileImages.length);
  const activeImage = profileImages[currentImageIndex] || "";
  
  // Add subtle jitter to the circle for that analogue feel
  const jitterRotation = interpolate(random(`rot-${flipSeed}`), [0, 1], [-2, 2]);
  const jitterScale = interpolate(random(`scale-${flipSeed}`), [0, 1], [0.98, 1.02]);

  // 3. Number Counting Logic
  // Using an eased interpolation instead of a spring prevents the number from bouncing
  // or drifting once it hits the target, ensuring it firmly stops exactly on the target number.
  const countProgress = interpolate(frame, [20, 60], [0, 1], {
    easing: Easing.out(Easing.cubic),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const currentNumber = Math.round(interpolate(countProgress, [0, 1], [0, targetNumber]));
  
  const numberPop = spring({
    frame: frame - 20,
    fps,
    config: { damping: 12, mass: 0.5 },
  });

  // 4. "Years" Text Entrance (Slides out over the circle)
  const mainWordEntrance = spring({
    frame: frame - 40,
    fps,
    config: { damping: 14 },
  });
  const mainWordAnimatedX = interpolate(mainWordEntrance, [0, 1], [-circleRadius * 2, circleRadius * mainWordOffsetX]);
  const mainWordOpacity = interpolate(mainWordEntrance, [0, 0.5, 1], [0, 1, 1]);

  // 5. "In the game" Subtext Entrance (Pops in below)
  const subtextEntrance = spring({
    frame: frame - 60,
    fps,
    config: { damping: 10, mass: 0.6 },
  });
  const subtextScale = interpolate(subtextEntrance, [0, 1], [0, 1]);
  const subtextRotate = interpolate(subtextEntrance, [0, 1], [-15, -4]);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      
      <div style={{ position: "absolute", left: centerX, top: centerY, transition: "none", zIndex: 10 }}>
        
        {/* Layer 1: Main Word (In Front of Circle) */}
        <div
          style={{
            position: "absolute",
            transform: `translate(${mainWordAnimatedX}px, ${circleRadius * mainWordOffsetY}px)`,
            opacity: mainWordOpacity,
            fontSize: s * mainWordFontSize,
            fontFamily: "'Abril Fatface', serif",
            color: primaryTextColor,
            zIndex: 5, // Brought to front
            textShadow: "4px 4px 0px rgba(0,0,0,0.08)",
            whiteSpace: "nowrap",
            transition: "none",
          }}
        >
          {mainWord}
        </div>

        {/* Layer 2: Center Image Circle */}
        <div
          style={{
            position: "absolute",
            transform: `translate(-50%, -50%) scale(${circleEntrance * jitterScale}) rotate(${jitterRotation}deg)`,
            width: circleRadius * 2,
            height: circleRadius * 2,
            borderRadius: "50%",
            overflow: "hidden",
            zIndex: 2,
            backgroundColor: "#222",
            boxShadow: "10px 10px 0px rgba(0,0,0,0.1)",
            transition: "none",
          }}
        >
          {activeImage && (
            <img 
              src={activeImage} 
              alt="Profile"
              style={{ 
                width: "100%", 
                height: "100%", 
                objectFit: "cover",
                filter: "grayscale(100%) contrast(120%) brightness(0.9)", // Halftone/print emulation
                transition: "none",
              }} 
            />
          )}
          {/* Subtle inner shadow for depth */}
          <div style={{
            position: "absolute",
            inset: 0,
            boxShadow: "inset 0px 0px 40px rgba(0,0,0,0.4)",
            pointerEvents: "none"
          }} />
        </div>

        {/* Layer 3: Counting Number (In front of circle, left side) */}
        <div
          style={{
            position: "absolute",
            transform: `translate(${circleRadius * numberOffsetX}px, ${circleRadius * numberOffsetY}px) scale(${interpolate(numberPop, [0, 1], [0.8, 1])})`,
            fontSize: s * numberFontSize,
            fontFamily: "'Abril Fatface', serif",
            color: primaryTextColor,
            zIndex: 3,
            textShadow: "8px 8px 0px rgba(0,0,0,0.1)",
            lineHeight: 1,
            transition: "none",
          }}
        >
          {currentNumber}
        </div>

        {/* Layer 4: Subtext Script (In front of circle, bottom right) */}
        <div
          style={{
            position: "absolute",
            transform: `translate(${circleRadius * subtextOffsetX}px, ${circleRadius * subtextOffsetY}px) scale(${subtextScale}) rotate(${subtextRotate}deg)`,
            fontSize: s * subtextFontSize,
            fontFamily: "'Caveat', cursive",
            color: primaryTextColor,
            zIndex: 4,
            whiteSpace: "nowrap",
            transformOrigin: "left center",
            transition: "none",
          }}
        >
          {subtextWord}
        </div>

      </div>

      {/* TEXTURES AND OVERLAYS (Applied globally on top of all elements) */}
      {!transparentBackground && <DotGridOverlay />}

      {/* Vox Style Crumpled Paper Overlay */}
      {!transparentBackground && paperTexture && (
        <img
          src={paperTexture}
          alt="Paper Texture Overlay"
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            width: "100%",
            height: "100%",
            objectFit: "cover",
            mixBlendMode: "multiply",
            opacity: 0.35,
            pointerEvents: "none",
            zIndex: 9998,
            filter: "grayscale(100%) contrast(150%) brightness(1.1)",
            transition: "none",
          }}
        />
      )}

      <NoiseOverlay />
    </AbsoluteFill>
  );
};

export default VoxStyleProfile;